const NAMES={'shape-choice':'Shape Spotter','shape-typed':'Postal Pro',sprint:'State Sprint',mapquest:'Map Quest',population:'Population Showdown',area:'Size Showdown',timeline:'Statehood Timeline','neighbors-one':'One of my Neighbors','neighbors-all':'All my Neighbors'};
const num=n=>(n||0).toLocaleString();
const seconds=ms=>(ms/1000).toFixed(1)+'s';
export function progressResults(progress,locations,practiceIds,challengeIds){
 return `<h2 class="progress-section-title">Game results</h2>${Object.entries(NAMES).map(([key,name])=>{
 if(key==='sprint')return `<section class="game-progress-card"><h3>State Sprint</h3>${['quiz','challenge'].map(mode=>{const totals=progress.sprintTotals?.[mode],s=(progress.sprintStats||[]).filter(s=>s.mode===mode),bestCorrect=Math.max(0,...s.map(s=>s.bestCorrect)),times=s.filter(s=>s.fastestMs!==null).map(s=>s.fastestMs),perfect=s.filter(s=>s.perfectMs!==null).map(s=>s.perfectMs);return `<div class="sprint-progress-mode"><h4>${mode==='quiz'?'60-second Quiz':'120-second Challenge'}</h4><p><strong>Lifetime points: ${num(totals?.points)}</strong><br>Best game score: ${num(totals?.bestScore)}</p><p>Best correct: ${bestCorrect}${mode==='challenge'?' / 50':' (across practice pools)'}${mode==='challenge'?`<br>Fastest all 50: ${times.length?seconds(Math.min(...times)):'—'}<br>Fastest perfect 50/50: ${perfect.length?seconds(Math.min(...perfect)):'—'}`:''}</p></div>`;}).join('')}</section>`;
 const g=progress.gameStats?.[key];return `<section class="game-progress-card"><h3>${name}</h3><p><strong>Lifetime points: ${num(g?.points)}</strong><br>Best game score: ${g?.bestScore?num(g.bestScore):'—'}</p>${g?`<p>${g.correct} / ${g.answered} correct · ${g.answered?Math.round(g.correct/g.answered*100):0}% accuracy<br>Current streak: ${g.streak} · longest: ${g.bestStreak}</p>`:''}</section>`;
 }).join('')}<p class="history-note">Best game scores for untimed games track each visit to that game. Switching games or reloading starts a new attempt; lifetime points keep growing. Earlier scores are included where saved data allows; unrecorded points cannot be recovered.${progress.legacyPoints?` ${num(progress.legacyPoints)} earlier points are included in the lifetime total without a per-game breakdown.`:''}</p>`;
}
